using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using F=System.Windows.Forms;

namespace GearLab {

 public sealed class MechanismTableDialog:F.Form {

  readonly F.DataGridView grid=new F.DataGridView();public MechanismTableDialog(string title,object rows){Text=title;Font=new Font("Segoe UI",10);Size=new Size(770,470);MinimumSize=new Size(600,360);StartPosition=F.FormStartPosition.CenterParent;grid.Dock=F.DockStyle.Fill;grid.AutoSizeColumnsMode=F.DataGridViewAutoSizeColumnsMode.Fill;grid.DataSource=rows;grid.BackgroundColor=Color.White;grid.DataError+=(s,e)=>{e.ThrowException=false;UiMessage.Show(this,"Введите число в правильном формате.","Параметры");};Controls.Add(grid);var bottom=new F.FlowLayoutPanel{Dock=F.DockStyle.Bottom,Height=48,Padding=new F.Padding(8)};var add=new F.Button{Text="Добавить",AutoSize=true};var remove=new F.Button{Text="Удалить строку",AutoSize=true};var ok=new F.Button{Text="Применить",AutoSize=true};var cancel=new F.Button{Text="Отмена",DialogResult=F.DialogResult.Cancel,AutoSize=true};add.Click+=(s,e)=>{var source=grid.DataSource as F.BindingSource;if(source!=null)source.AddNew();};remove.Click+=(s,e)=>{foreach(F.DataGridViewRow row in grid.SelectedRows)if(!row.IsNewRow)grid.Rows.Remove(row);};ok.Click+=(s,e)=>{if(!ValidateChildren())return;grid.EndEdit();var source=grid.DataSource as F.BindingSource;if(source!=null)source.EndEdit();DialogResult=F.DialogResult.OK;};bottom.Controls.AddRange(new F.Control[]{add,remove,ok,cancel});Controls.Add(bottom);CancelButton=cancel;AcceptButton=ok;grid.DataBindingComplete+=(s,e)=>{foreach(F.DataGridViewColumn c in grid.Columns)switch(c.DataPropertyName){case "Name":c.HeaderText="Название";break;case "X":c.HeaderText="X, мм";break;case "Y":c.HeaderText="Y, мм";break;case "Diameter":c.HeaderText="Диаметр, мм";break;case "Bore":c.HeaderText="Внутр. Ø, мм";break;case "Length":c.HeaderText="Длина, мм";break;case "Depth":c.HeaderText="Глубина сверху (0=сквозное), мм";break;}};}

 }

 public sealed class MechanismLinkDialog:F.Form {

  public readonly F.ComboBox From=new EditorComboBox(),To=new EditorComboBox(),Type=new EditorComboBox();public readonly SafeNumber Efficiency=new SafeNumber(),Angle=new SafeNumber();public readonly F.CheckBox Arrange=new F.CheckBox();

  public MechanismLinkDialog(MechanismProject p,string selected){Text="Связь между валами";Font=new Font("Segoe UI",10);ClientSize=new Size(580,390);FormBorderStyle=F.FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=F.FormStartPosition.CenterParent;var panel=new F.FlowLayoutPanel{Dock=F.DockStyle.Fill,FlowDirection=F.FlowDirection.TopDown,WrapContents=false,Padding=new F.Padding(18)};Controls.Add(panel);Type.DropDownStyle=From.DropDownStyle=To.DropDownStyle=F.ComboBoxStyle.DropDownList;Type.Width=From.Width=To.Width=530;Type.Items.AddRange(new[]{"Внешнее зацепление шестерён","Открытый ремень между шкивами","Соосная жёсткая муфта валов"});Action fill=()=>{string kind=Type.SelectedIndex==0?"gear":Type.SelectedIndex==1?"pulley":"shaft";From.Items.Clear();To.Items.Clear();foreach(var a in p.Parts.Where(a=>a.Kind==kind)){From.Items.Add(a);To.Items.Add(a);}if(From.Items.Count>0){int index=From.Items.Cast<MechanismPart>().ToList().FindIndex(a=>a.Id==selected);From.SelectedIndex=Math.Max(0,index);To.SelectedIndex=From.Items.Count>1?(From.SelectedIndex+1)%From.Items.Count:0;}};Type.SelectedIndexChanged+=(s,e)=>fill();panel.Controls.Add(Type);panel.Controls.Add(new F.Label{Text="Ведущая деталь / вал",Width=530,Height=23});panel.Controls.Add(From);panel.Controls.Add(new F.Label{Text="Ведомая деталь / вал",Width=530,Height=23});panel.Controls.Add(To);var row=new F.FlowLayoutPanel{Width=530,Height=40};row.Controls.Add(new F.Label{Text="КПД (0…1)",Width=100});Efficiency.DecimalPlaces=3;Efficiency.Minimum=.001m;Efficiency.Maximum=1;Efficiency.Value=.97m;row.Controls.Add(Efficiency);row.Controls.Add(new F.Label{Text="Направление, °",Width=130});Angle.DecimalPlaces=1;Angle.Minimum=-360;Angle.Maximum=360;Angle.Width=90;row.Controls.Add(Angle);panel.Controls.Add(row);Arrange.Text="Автоматически расположить ведомый вал";Arrange.Checked=true;Arrange.Width=530;Arrange.Height=32;panel.Controls.Add(Arrange);panel.Controls.Add(new F.Label{Text="Оси валов параллельны Z. КПД — заданный коэффициент, а не результат расчёта трения.",Width=530,Height=45,ForeColor=Color.SlateGray});var buttons=new F.FlowLayoutPanel{Width=530,Height=40};var ok=new F.Button{Text="Соединить",Width=140};ok.Click+=(s,e)=>{if(From.SelectedItem==null||To.SelectedItem==null||ReferenceEquals(From.SelectedItem,To.SelectedItem)){UiMessage.Show(this,"Выберите две разные детали.");return;}decimal v;if(!Efficiency.TryRead(out v)||!Angle.TryRead(out v))return;DialogResult=F.DialogResult.OK;};var cancel=new F.Button{Text="Отмена",Width=110,DialogResult=F.DialogResult.Cancel};buttons.Controls.AddRange(new F.Control[]{ok,cancel});panel.Controls.Add(buttons);CancelButton=cancel;Type.SelectedIndex=0;}

  public MechanismLink Create(){return new MechanismLink{FromId=((MechanismPart)From.SelectedItem).Id,ToId=((MechanismPart)To.SelectedItem).Id,Kind=Type.SelectedIndex==0?"gear":Type.SelectedIndex==1?"belt":"coupling",Efficiency=(double)Efficiency.Value,PlacementAngle=(double)Angle.Value};}

 }

 public sealed class MechanismSketchDialog:F.Form {

  readonly F.Panel canvas=new F.Panel();readonly F.DataGridView table=new F.DataGridView();readonly List<MechanismPoint> points;readonly F.BindingSource source=new F.BindingSource();double scale=6;bool closed;public List<MechanismPoint> Points{get{return points;}}

  public MechanismSketchDialog(IEnumerable<MechanismPoint> original){points=original.Select(p=>new MechanismPoint(p.X,p.Y)).ToList();Text="Эскиз XY → выдавливание";Font=new Font("Segoe UI",10);Size=new Size(1000,700);MinimumSize=new Size(760,520);StartPosition=F.FormStartPosition.CenterParent;var split=new F.SplitContainer{Size=new Size(980,580),Dock=F.DockStyle.Fill,SplitterDistance=670,FixedPanel=F.FixedPanel.Panel2};Controls.Add(split);canvas.Dock=F.DockStyle.Fill;canvas.BackColor=Color.FromArgb(246,249,252);canvas.Paint+=Draw;canvas.MouseDown+=(s,e)=>{if(e.Button!=F.MouseButtons.Left)return;points.Add(new MechanismPoint(Math.Round((e.X-canvas.Width/2)/scale*2)/2,Math.Round((canvas.Height/2-e.Y)/scale*2)/2));closed=false;source.ResetBindings(false);canvas.Invalidate();};canvas.MouseWheel+=(s,e)=>{scale=Math.Max(1,Math.Min(50,scale*Math.Exp(e.Delta*.001)));canvas.Invalidate();};canvas.Resize+=(s,e)=>canvas.Invalidate();split.Panel1.Controls.Add(canvas);source.DataSource=new System.ComponentModel.BindingList<MechanismPoint>(points);table.Dock=F.DockStyle.Fill;table.DataSource=source;table.AutoSizeColumnsMode=F.DataGridViewAutoSizeColumnsMode.Fill;table.DataError+=(s,e)=>e.ThrowException=false;table.CellValueChanged+=(s,e)=>canvas.Invalidate();table.RowsRemoved+=(s,e)=>canvas.Invalidate();split.Panel2.Controls.Add(table);var bottom=new F.FlowLayoutPanel{Dock=F.DockStyle.Bottom,Height=90,Padding=new F.Padding(8)};Controls.Add(bottom);bottom.Controls.Add(new F.Label{Text="ЛКМ — вершина (сетка 0,5 мм); координаты справа. Колесо — масштаб. Контур замыкается последней точкой к первой.",Width=950,Height=28});Action<string,Action> button=(text,act)=>{var b=new F.Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>act();bottom.Controls.Add(b);};button("Удалить последнюю",()=>{if(points.Count>0)points.RemoveAt(points.Count-1);source.ResetBindings(false);canvas.Invalidate();});button("Очистить",()=>{points.Clear();source.ResetBindings(false);canvas.Invalidate();});button("Прямоугольник 40×30",()=>{points.Clear();points.AddRange(new[]{new MechanismPoint(-20,-15),new MechanismPoint(20,-15),new MechanismPoint(20,15),new MechanismPoint(-20,15)});source.ResetBindings(false);closed=true;canvas.Invalidate();});button("Выдавить / применить",()=>{table.EndEdit();source.EndEdit();if(!MechanismCad.SimplePolygon(points.Select(p=>new PointF((float)p.X,(float)p.Y)).ToArray())){UiMessage.Show(this,"Нужен контур из минимум трёх вершин без самопересечений и повторяющихся точек.");return;}DialogResult=F.DialogResult.OK;});var cancel=new F.Button{Text="Отмена",DialogResult=F.DialogResult.Cancel,Height=32};bottom.Controls.Add(cancel);CancelButton=cancel;closed=points.Count>2;}

  void Draw(object sender,F.PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;float cx=canvas.Width/2f,cy=canvas.Height/2f;double spacing=scale*5;using(var grid=new Pen(Color.FromArgb(225,232,240)))for(double x=cx%spacing;x<canvas.Width;x+=spacing)g.DrawLine(grid,(float)x,0,(float)x,canvas.Height);using(var grid=new Pen(Color.FromArgb(225,232,240)))for(double y=cy%spacing;y<canvas.Height;y+=spacing)g.DrawLine(grid,0,(float)y,canvas.Width,(float)y);g.DrawLine(Pens.SlateGray,cx,0,cx,canvas.Height);g.DrawLine(Pens.SlateGray,0,cy,canvas.Width,cy);var p=points.Select(v=>new PointF((float)(cx+v.X*scale),(float)(cy-v.Y*scale))).ToArray();if(p.Length>2&&closed){using(var fill=new SolidBrush(Color.FromArgb(40,70,140,210)))g.FillPolygon(fill,p);}if(p.Length>1)using(var pen=new Pen(Color.FromArgb(35,112,180),2)){g.DrawLines(pen,p);if(p.Length>2){pen.DashStyle=System.Drawing.Drawing2D.DashStyle.Dash;g.DrawLine(pen,p.Last(),p.First());}}for(int i=0;i<p.Length;i++){g.FillEllipse(Brushes.DarkOrange,p[i].X-4,p[i].Y-4,8,8);g.DrawString((i+1).ToString(),Font,Brushes.DarkSlateGray,p[i].X+5,p[i].Y+3);}g.DrawString("XY · мм · шаг ввода 0,5 мм",Font,Brushes.SlateGray,12,12);}

 }

}


